import { test, expect } from '@playwright/test';

test.describe('Skip Navigation Links Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with skip navigation links
    await page.goto('http://localhost:3000');
  });

  test('should have skip navigation link as first focusable element', async ({ page }) => {
    // Get all focusable elements in tab order
    const skipLink = page.getByRole('link', { name: /skip to main content/i });

    // Verify skip link exists
    await expect(skipLink).toBeVisible();

    // Tab to the first element - should be the skip link
    await page.keyboard.press('Tab');

    // Check if skip link is focused
    const focusedElement = await page.evaluate(() => {
      return document.activeElement?.getAttribute('aria-label') || 
             document.activeElement?.textContent;
    });

    expect(focusedElement).toContain('skip');
  });

  test('skip navigation link should be keyboard accessible and functional', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    const mainContent = page.getByRole('main');

    // Focus the skip link
    await skipLink.focus();

    // Verify it's focused
    const isFocused = await skipLink.evaluate((el) => {
      return el === document.activeElement;
    });
    expect(isFocused).toBe(true);

    // Press Enter to activate the link
    await page.keyboard.press('Enter');

    // Verify main content is now focused or visible
    await expect(mainContent).toBeVisible();
  });

  test('skip navigation link should be visually hidden but accessible', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to main content/i });

    // Verify the link exists in the DOM
    await expect(skipLink).toBeAttached();

    // Check if it's accessible via keyboard
    const isAccessible = await skipLink.evaluate((el) => {
      const style = window.getComputedStyle(el);
      // Check if element is hidden but still in tab order
      return el.offsetParent !== null || el.getAttribute('aria-hidden') !== 'true';
    });

    expect(isAccessible).toBe(true);
  });

  test('skip navigation link should appear before other interactive elements in tab order', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    const firstButton = page.getByRole('button').first();

    // Get tab indices
    const skipLinkTabIndex = await skipLink.evaluate((el) => {
      return el.getAttribute('tabindex');
    });

    const buttonTabIndex = await firstButton.evaluate((el) => {
      return el.getAttribute('tabindex');
    });

    // Skip link should have tabindex 0 or no tabindex (default 0)
    // and should come before other elements in natural tab order
    const skipLinkIndex = skipLinkTabIndex === null ? 0 : parseInt(skipLinkTabIndex);
    const buttonIndex = buttonTabIndex === null ? 0 : parseInt(buttonTabIndex);

    expect(skipLinkIndex).toBeLessThanOrEqual(buttonIndex);
  });

  test('skip navigation link should have proper ARIA attributes', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to main content/i });

    // Verify the link has proper role
    const role = await skipLink.evaluate((el) => {
      return el.getAttribute('role') || el.tagName.toLowerCase();
    });
    expect(role).toBe('a');

    // Verify it has accessible name
    const accessibleName = await skipLink.evaluate((el) => {
      return el.textContent || el.getAttribute('aria-label');
    });
    expect(accessibleName).toBeTruthy();
    expect(accessibleName?.toLowerCase()).toContain('skip');
  });

  test('skip navigation link should navigate to main content area', async ({ page }) => {
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    const mainContent = page.getByRole('main');

    // Get the href of skip link
    const href = await skipLink.getAttribute('href');

    // Verify it points to main content
    if (href && href.startsWith('#')) {
      const targetId = href.substring(1);
      const targetElement = page.locator(`#${targetId}`);
      await expect(targetElement).toBeAttached();
    }
  });
});
